import{_ as i,o as a,c as t,ag as e}from"./chunks/framework.CZxGLIO_.js";const c=JSON.parse('{"title":"备份、恢复与日志","description":"使用 Rooster 一致性快照、离线恢复、日志归档与保留清理接口。","frontmatter":{"title":"备份、恢复与日志","description":"使用 Rooster 一致性快照、离线恢复、日志归档与保留清理接口。"},"headers":[],"relativePath":"docs/rooster/maintenance/index.md","filePath":"docs/rooster/maintenance/index.md"}'),n={name:"docs/rooster/maintenance/index.md"};function d(h,s,l,o,p,r){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="备份、恢复与日志" tabindex="-1">备份、恢复与日志 <a class="header-anchor" href="#备份、恢复与日志" aria-label="Permalink to &quot;备份、恢复与日志&quot;">​</a></h1><p>以下接口已存在于核对的源码提交 <code>96c86ae</code>，旧构建可能不具备。先查看运行实例的 <code>/api/docs</code>，按 <a href="./../installation/">安装</a> 更新后再使用。</p><h2 id="数据目录与备份范围" tabindex="-1">数据目录与备份范围 <a class="header-anchor" href="#数据目录与备份范围" aria-label="Permalink to &quot;数据目录与备份范围&quot;">​</a></h2><p>数据目录包含 <code>rooster.db</code> 和 <code>logs/</code>。<code>ROOSTER_DATA_DIR</code> 可显式设置路径，否则使用系统用户配置目录下的 <code>Rooster</code>。</p><table tabindex="0"><thead><tr><th>方式</th><th>包含</th><th>不包含</th></tr></thead><tbody><tr><td><code>GET /api/export</code></td><td>带版本的任务定义 JSON、环境变量</td><td>执行历史和日志；不是完整恢复备份</td></tr><tr><td><code>GET /api/backup</code></td><td>一致性 SQLite 快照，包含已提交 WAL 数据、任务与执行元数据</td><td>日志文件</td></tr><tr><td>单独保存 <code>logs/</code></td><td>当前与轮转日志</td><td>任务配置和执行数据库</td></tr></tbody></table><p>导出与快照可能含环境变量中的密钥，应保存在私有目录。不要直接复制正在写入的 <code>rooster.db</code> 主文件来代替一致性快照。</p><h2 id="下载在线快照" tabindex="-1">下载在线快照 <a class="header-anchor" href="#下载在线快照" aria-label="Permalink to &quot;下载在线快照&quot;">​</a></h2><p>POSIX shell 示例，创建新的私有备份目录：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ROOSTER_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:9090</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">umask</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 077</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BACKUP_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mktemp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/rooster-backup.XXXXXX&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ROOSTER_BASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/export&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BACKUP_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/tasks.json&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ROOSTER_BASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/backup&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BACKUP_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/rooster.db&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">printf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%s\\n&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BACKUP_DIR</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>检查每条下载命令成功后再使用文件。每次使用新目录，避免覆盖上一份有效备份；需要日志时另行保存 <code>logs/</code>。</p><h2 id="离线恢复到新目录" tabindex="-1">离线恢复到新目录 <a class="header-anchor" href="#离线恢复到新目录" aria-label="Permalink to &quot;离线恢复到新目录&quot;">​</a></h2><p>在对应版本的源码根目录运行，替换备份与目标路径：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/rooster-restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup/rooster.db</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -destination</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/new-rooster-data</span></span></code></pre></div><p>目标目录必须尚不存在，父目录应已存在。恢复命令不会覆盖现有数据目录，也不会执行任务。恢复结果具有以下行为：</p><ul><li>所有任务设为停用。</li><li>中断的执行记录标记失败，日志路径调整到新目录。</li><li>日志文件不会从快照恢复，需要另外保留归档。</li><li>带非空 WAL 的原始数据库来源会被拒绝，使用下载的独立快照。</li></ul><p>使用新目录和独立端口启动实例，检查任务配置、环境变量和历史，再手动验证任务。确认后逐项启用；迁移时先退出旧实例，避免两套实例同时运行同一业务任务。</p><h2 id="当前日志与轮转归档" tabindex="-1">当前日志与轮转归档 <a class="header-anchor" href="#当前日志与轮转归档" aria-label="Permalink to &quot;当前日志与轮转归档&quot;">​</a></h2><p>日志在 20 MB 时轮转，保留三个压缩备份。普通日志接口只返回当前文件最后 64 KiB，不能凭页面上日志开头判断执行没有更早输出。</p><table tabindex="0"><thead><tr><th>请求</th><th>返回内容</th></tr></thead><tbody><tr><td><code>GET /api/executions/{id}/logs</code></td><td>当前日志尾部</td></tr><tr><td><code>GET /api/executions/{id}/logs?download=1</code></td><td>完整当前文件，不含轮转归档</td></tr><tr><td><code>GET /api/executions/{id}/logfiles</code></td><td>可用归档名称和大小</td></tr><tr><td><code>GET /api/executions/{id}/logs?archive={name}</code></td><td>解压归档的最后 64 KiB，解压上限 32 MiB</td></tr><tr><td><code>GET /api/executions/{id}/logs?archive={name}&amp;download=1</code></td><td>原始压缩归档</td></tr></tbody></table><p>只使用 <code>logfiles</code> 返回的名称，并对查询参数做 URL 编码。刚派发执行时日志文件可能暂未创建，短暂 <code>404</code> 应结合执行状态判断。</p><h2 id="清理历史-先预览" tabindex="-1">清理历史：先预览 <a class="header-anchor" href="#清理历史-先预览" aria-label="Permalink to &quot;清理历史：先预览&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail-with-body</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ROOSTER_BASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/maintenance/retention&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;days&quot;:30,&quot;keepPerTask&quot;:100,&quot;dryRun&quot;:true}&#39;</span></span></code></pre></div><p>只筛选已结束、早于截止时间，且不属于每个任务最新保留条数内的记录，活动执行不参与。<code>days</code> 范围 1–36500，<code>keepPerTask</code> 至少 1；发送 <code>{}</code> 使用上述默认值并预览。</p><p>检查返回的 <code>candidates</code>、<code>files</code>、<code>bytes</code>、<code>errors</code>，备份后才把同一请求的 <code>dryRun</code> 改为 <code>false</code> 执行删除。即使 HTTP 为 <code>200</code>，也要检查 <code>errors</code>：文件删除和记录删除不是原子操作，部分失败可能已经删除某些日志。<code>files</code> 与 <code>bytes</code> 表示计划，不保证实际释放空间。</p><p>当前没有自动清理日程或总磁盘配额。日志轮转限制单个执行文件，不等于整个数据目录不会继续增长。</p><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/httpapi/agent/references/api.md" target="_blank" rel="noreferrer">备份与保留契约</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/cmd/rooster-restore/main.go" target="_blank" rel="noreferrer">恢复入口</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/roosterapp/restore.go" target="_blank" rel="noreferrer">恢复实现</a>。</p>`,27)])])}const F=i(n,[["render",d]]);export{c as __pageData,F as default};
